            >
              {item.label}
            </a>
          ))}
          <a
            href="https://wa.me/6285758287612"
            target="_blank"
            rel="noopener noreferrer"
            className="px-6 py-2 bg-white text-black font-bold rounded-full hover:bg-gray-200 transition-colors text-sm"
          >
            Contact
